'use strict';
const $=s=>document.querySelector(s);
const PATH={home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',calendar:'M3 6h18v15H3ZM7 3v6m10-6v6M3 11h18M7 15h2m4 0h2',plan:'m3 7 2 2 4-4m3 2h9M3 16l2 2 4-4m3 2h9',chart:'M4 20V10m5 10V5m5 15V8m5 12V3M2 21h20',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0ZM6 11v1a6 6 0 0 0 12 0v-1M12 18v4m-4 0h8',image:'M3 4h18v16H3ZM3 16l5-5 5 5 3-3 5 5M15 8h.01',user:'M8 7a4 4 0 1 0 8 0 4 4 0 1 0-8 0M4 21v-2a8 6 0 0 1 16 0v2Z',left:'m15 5-7 7 7 7',right:'m9 5 7 7-7 7',down:'m5 9 7 7 7-7',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0M12 7v5l3 2',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0ZM10 10a2 2 0 1 0 4 0 2 2 0 1 0-4 0',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4',close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',book:'M12 5C9 3 5 3 3 4v16c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v16',research:'M8 3h8M10 3v7L4 20h16l-6-10V3M8 14h8',folder:'M3 6h7l2 3h9v12H3Z',heart:'M12 21S2 15 2 8c0-6 8-7 10-1 2-6 10-5 10 1 0 7-10 13-10 13Z',offline:'m3 3 18 18M8 6a12 12 0 0 1 13 4M3 10l2-1m2 5 2-1m5 0 3 1M11 18h2',send:'m5 12 7-8 7 8M12 4v17',info:'M12 11v6m0-10h.01M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0',undo:'M4 9h10a6 6 0 0 1 0 12H9M4 9l5-5M4 9l5 5'};
const icon=name=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${PATH[name]||PATH.spark}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const FIXTURE='周三17点到18点开组会，会议室6412，帮我调整冲突的学习计划。';
const initial=()=>({view:'today',day:TODAY,range:'week',metric:'scheduled',category:null,tags:[],filterDay:null,expanded:false,empty:false,offline:false,modal:null,stage:'input',step:0,text:'',reminder:30,eventCategory:'research',eventTags:['meeting'],moved:false,undoAvailable:false,moduleVisible:true});
let state=initial(),rows=seedData(),processTimer,toastTimer,returnFocus,numberFrame;
const scrollByView={};
const conflict=()=>rows.some(r=>r.id==='meeting-new')&&!state.moved;
const meeting=()=>rows.find(r=>r.id==='meeting-new');
const reduced=()=>document.body.classList.contains('reduced')||matchMedia('(prefers-reduced-motion: reduce)').matches;
function notify(text,undo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${esc(text)}</span>${undo?'<button data-action="undo">撤销</button>':''}`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function categoryStyle(key){return `--category-color:${CATEGORY[key].color};--category-pale:${CATEGORY[key].pale}`;}
function rowButton(r){const current=r.date===TODAY&&r.start<='11:40'&&r.end>'11:40';const past=r.date<TODAY||(r.date===TODAY&&r.end<='11:40');return `<button class="schedule-row ${current?'current':past?'past':''}" data-action="detail" data-id="${r.id}"><div class="time">${r.start||r.due||'待定'}<small>${r.end||'截止'}</small></div><div class="row-content" style="--row-color:${CATEGORY[r.category].color}"><b>${esc(r.title)}</b><small>${esc(r.place||'个人计划')}</small></div><span class="row-state ${current?'current':''}">${current?'进行中':past?'已结束':r.kind==='plan'?'计划':icon('right')}</span></button>`;}
function section(title,action='',label=''){return `<div class="section-title"><h2>${title}</h2>${action?`<button data-action="${action}">${label}</button>`:''}</div>`;}
function weekStrip(){return `<div class="week-strip" aria-label="选择日期">${Array.from({length:7},(_,i)=>{const day=dateAdd('2026-09-21',i);return `<button data-action="day" data-day="${day}" class="${day===state.day?'selected':''}" aria-label="${dateLabel(day)} 周${weekday(day)}">${weekday(day)}<b>${Number(day.slice(8))}</b><i class="day-dot"></i></button>`;}).join('')}</div>`;}
function bookArt(){return '<svg class="class-art" aria-hidden="true" viewBox="0 0 90 100"><ellipse cx="48" cy="84" rx="35" ry="7" fill="#c9e2d4"/><rect class="book" x="17" y="25" rx="7" width="59" height="56"/><rect class="paper" x="13" y="16" rx="6" width="59" height="61"/><path class="line" d="M25 34h32M25 44h23M25 54h29"/><path d="M56 15v19l6-4 6 4V15" fill="#d6bc85"/><circle cx="14" cy="75" r="5" fill="#c8ded3"/></svg>';}
function todayView(){const weekData=summarize(rows);const miniMax=Math.max(1,...Object.values(weekData.days));const courseRows=rows.filter(r=>r.date===state.day&&r.kind==='course');const future=courseRows.find(r=>r.start>'11:40');const next=state.day===TODAY?future:courseRows[0];const own=rows.filter(r=>r.date===state.day&&r.kind!=='course');return `${weekStrip()}${next?`<div class="next-class"><div class="next-top"><span class="live-dot"></span>${state.day===TODAY?'下一节课':'第一节课'}<span style="margin-left:10px">${next.start}—${next.end}</span></div><h2>${next.title}</h2><div class="next-detail">${icon('pin')}${next.place}</div>${bookArt()}</div>`:''}${section(state.day===TODAY?'今日课程':`${dateLabel(state.day)}的课程`,'schedule','查看日程 →')}<div class="list-card">${courseRows.map(rowButton).join('')||'<div class="empty-state"><h3>当天没有课程</h3></div>'}</div>${state.day===TODAY?`<button class="deadline-card" data-action="${conflict()?'replan':'detail'}" data-id="java"><span class="deadline-icon">${icon('bell')}</span><div><b>${conflict()?'组会与报告计划重叠':'Java实验报告 · 周五18:00截止'}</b><small>${conflict()?'周三17:00—18:00 · 查看调整方案':'剩余1小时，已安排学习时间'}</small></div>${icon('right')}</button>`:''}${own.length?`${section('其他安排')}<div class="list-card">${own.map(rowButton).join('')}</div>`:''}${section('快捷查看','modules','编辑')}${state.moduleVisible?`<div class="widget-grid"><button class="widget" data-action="analytics"><div class="widget-heading">${icon('chart')}本周统计</div><strong>${hourLabel(summarize(rows).total)}<small>小时</small></strong><p>已安排时长</p><div class="mini-bars" aria-hidden="true">${Array.from({length:7},(_,i)=>`<i style="height:${(weekData.days[dateAdd('2026-09-21',i)]||0)/miniMax*100}%"></i>`).join('')}</div></button><button class="widget green" data-action="plans"><div class="widget-heading">${icon('plan')}个人计划</div><strong>1<small>项报告</small></strong><p>${state.moved?'周四16:00—17:00':'周三17:00—18:00'}</p></button></div>`:'<button class="text-button" data-action="modules">添加快捷模块</button>'}`;}
function selectedSummary(){return summarize(rows,{range:state.range,metric:state.metric,category:state.category,tags:state.tags,day:state.filterDay,empty:state.empty});}
function periodBuckets(summary){const length=Math.round((Date.parse(summary.to)-Date.parse(summary.from))/86400000)+1;const step=length>35?21:length>7?5:1;const buckets=[];for(let i=0;i<length;i+=step){const day=dateAdd(summary.from,i),end=dateAdd(summary.from,Math.min(i+step-1,length-1));const minutes=Object.entries(summary.days).filter(([d])=>d>=day&&d<=end).reduce((n,[,v])=>n+v,0);buckets.push({day,end,minutes,label:step===1?weekday(day):shortDate(day),single:step===1});}return buckets;}
function analyticsView(){const s=selectedSummary();if(state.empty)return `<div class="range-selector"><button class="selected">${{week:'本周',month:'本月',semester:'本学期'}[state.range]}</button></div><div class="period-row">${shortDate(s.from)}—${shortDate(s.to)}</div><div class="empty-state" style="padding:48px 20px">${icon('chart')}<h3>当前范围暂无记录</h3><p>添加日程或记录实际时长后，可以在这里查看统计。</p><button class="text-button" data-action="empty-stats">恢复示例数据</button></div>`;const base=summarize(rows,{range:state.range,metric:state.metric,tags:state.tags,empty:state.empty});const buckets=periodBuckets(s),max=Math.max(60,...buckets.map(b=>b.minutes));const maxCategory=Math.max(60,...Object.values(base.totals));const availableTags=[...new Set(rows.filter(r=>r.date>=s.from&&r.date<=s.to&&(!state.category||r.category===state.category)).flatMap(r=>r.tags))];const list=state.expanded?s.details:s.details.slice(0,5);return `<div class="range-selector" aria-label="统计时间范围">${[['week','本周'],['month','本月'],['semester','本学期']].map(([v,n])=>`<button class="${state.range===v?'selected':''}" data-action="range" data-range="${v}" aria-pressed="${state.range===v}">${n}</button>`).join('')}</div><div class="period-row"><span>${shortDate(s.from)}—${shortDate(s.to)}</span><select class="metric-select" id="metric" aria-label="统计口径"><option value="scheduled" ${state.metric==='scheduled'?'selected':''}>已安排时长</option><option value="actual" ${state.metric==='actual'?'selected':''}>实际记录时长</option></select></div><div class="analytics-summary"><div class="summary-label">${state.category?CATEGORY[state.category].name+' · ':''}${state.metric==='actual'?'实际记录':'已安排'}</div><div class="summary-number"><span id="animated-total" data-minutes="${s.total}" data-known="${s.known}">${state.metric==='actual'&&!s.known?'—':hourLabel(s.total)}</span><small>小时</small></div><button class="summary-info" data-action="stat-info">统计说明</button></div><div class="chart-card"><div class="chart-head"><h2>时间分布</h2><button data-action="clear-filter">${state.category||state.tags.length?'清除筛选':'按分类查看'}</button></div>${Object.entries(CATEGORY).map(([key,c])=>`<button class="category-bar ${state.category===key?'selected':''}" style="${categoryStyle(key)}" data-action="category" data-category="${key}" aria-pressed="${state.category===key}" aria-label="筛选${c.name}"><div class="category-row"><span class="category-label"><i class="color-dot"></i>${c.name}</span><span class="category-value">${state.metric==='actual'&&!base.knownByCategory[key]?'—':hourLabel(base.totals[key])+'小时'}</span></div><div class="bar-track"><div class="bar-fill" style="width:${base.totals[key]/maxCategory*100}%"></div></div></button>`).join('')}</div><div class="tag-strip" aria-label="标签筛选">${availableTags.map(t=>`<button class="${state.tags.includes(t)?'selected':''}" data-action="tag" data-tag="${t}" aria-pressed="${state.tags.includes(t)}">${TAG_NAMES[t]}</button>`).join('')}</div>${state.category||state.tags.length?`<div class="selection-caption">已筛选 ${state.category?`<span class="filter-pill">${CATEGORY[state.category].name}</span>`:''}${state.tags.map(t=>`<span class="filter-pill">${TAG_NAMES[t]}</span>`).join('')}</div>`:''}<div class="chart-card"><div class="chart-head"><h2>${state.range==='week'?'每天的安排':'时间分布趋势'}</h2><span class="notice-text" style="margin:0">${state.metric==='actual'?'实际记录':'已安排'} · 小时</span></div><div class="daily-chart">${buckets.map(b=>`<button class="day-bar ${state.filterDay===b.day?'selected':''}" data-action="chart-day" data-day="${b.day}" data-single="${b.single}" data-end="${b.end}" aria-label="${dateLabel(b.day)}${b.single?'':'至'+dateLabel(b.end)} ${hourLabel(b.minutes)}小时"><span class="day-value">${b.minutes?hourLabel(b.minutes):'—'}</span><i class="column" style="height:${b.minutes/max*76}px"></i><small>${b.label}</small></button>`).join('')}</div></div>${s.missing?`<p class="notice-text">${s.missing}条安排没有${state.metric==='actual'?'实际时长记录':'完整时间'}，未计入。</p>`:''}${section(state.filterDay?`${dateLabel(state.filterDay)}的安排`:'相关日程',state.filterDay?'clear-day':'',state.filterDay?'查看全部':'')}<div class="detail-list">${list.map(r=>detailEntry(r)).join('')||`<div class="empty-state">${icon('chart')}<h3>当前范围暂无记录</h3><p>可以切换时间范围或清除筛选。</p></div>`}</div>${s.details.length>5&&!state.expanded?`<button class="load-more" data-action="expand-list">查看全部${s.details.length}条日程</button>`:''}<button class="quiet-link" data-action="analytics-query">${icon('spark')}让AI分析当前范围${icon('right')}</button>`;}
function detailEntry(r){const n=state.metric==='actual'?r.actual:duration(r);return `<button class="detail-entry" data-action="detail" data-id="${r.id}" style="${categoryStyle(r.category)}"><span class="entry-symbol">${icon(CATEGORY[r.category].icon)}</span><span class="entry-info"><b>${r.title}</b><small>${shortDate(r.date)} ${r.start?`${r.start}—${r.end}`:r.due+'截止'} · ${r.tags.map(t=>TAG_NAMES[t]).join(' / ')}</small></span><span class="entry-time">${n==null?'未计时':hourLabel(n)+'h'}</span></button>`;}
function supportView(){if(state.view==='schedule')return `${weekStrip()}${section(`${dateLabel(state.day)} 周${weekday(state.day)}`)}<div class="list-card">${rows.filter(r=>r.date===state.day).sort((a,b)=>(a.start||a.due).localeCompare(b.start||b.due)).map(rowButton).join('')||'<div class="empty-state"><h3>当天没有安排</h3></div>'}</div><button class="quiet-link" data-action="analytics">${icon('chart')}查看统计分析${icon('right')}</button>`;if(state.view==='plans')return `${conflict()?'<div class="offline">组会与报告计划在周三17:00重叠</div>':''}<div class="result-card"><div class="result-kicker">周五18:00截止</div><h3>Java实验报告</h3><div class="result-line">${icon('clock')}<span>${state.moved?'周四16:00—17:00':'周三17:00—18:00'}<br><small>剩余工作1小时 · 已安排1小时</small></span></div>${state.undoAvailable?'<button class="text-button" data-action="undo">撤销本次调整</button>':''}</div><button class="primary" data-action="replan">调整报告计划</button><button class="quiet-link" data-action="analytics">${icon('chart')}查看统计分析${icon('right')}</button>`;return `<div class="result-card"><div class="result-kicker">2026—2027 第一学期</div><h3>第4周 <small style="font-size:12px;color:#9792ab">/ 共20周</small></h3><p class="plain-copy">8月31日开学</p><button class="primary" data-action="analytics">${icon('chart')} 统计分析</button></div>${section('近期事项')}<div class="detail-list">${rows.filter(r=>r.id==='deadline'||r.id==='meeting-new').map(detailEntry).join('')}</div>`;}
function render({keepScroll=true}={}){const old=$('#main').scrollTop;const previousText=$('#animated-total')?.textContent;const previousMinutes=previousText&&previousText!=='—'?Number(previousText)*60:0;const previousWidths=new Map([...document.querySelectorAll('.category-bar')].map(el=>[el.dataset.category,el.querySelector('.bar-fill').getBoundingClientRect().width]));const title=state.view==='today'?(state.day===TODAY?'今日安排':dateLabel(state.day)+'的安排'):({analytics:'统计分析',schedule:'日程',plans:'计划',semester:'本学期'}[state.view]);$('#header').innerHTML=`<div class="header-row"><div class="${state.view==='analytics'?'back-title':''}">${state.view==='analytics'?`<button class="icon-button" data-action="back" aria-label="返回">${icon('left')}</button>`:''}<div><h1 class="page-title">${title}</h1>${state.view==='today'?`<p class="header-date">${dateLabel(state.day)} · 周${weekday(state.day)} · 第4周</p>`:''}</div></div><div class="header-actions">${state.view==='today'?`<button class="icon-button" data-action="analytics" aria-label="统计分析">${icon('chart')}</button>`:''}<button class="icon-button tint" data-action="account" aria-label="账户与设置">${icon('user')}</button></div></div>`;$('#main').innerHTML=`${state.offline?`<div class="offline">${icon('offline')}离线 · 正在查看本机保存的记录</div>`:''}<div class="view">${state.view==='today'?todayView():state.view==='analytics'?analyticsView():supportView()}</div>`;$('#main').scrollTop=keepScroll?old:0;$('#dock').innerHTML=`<div class="dock-entry"><button class="ask" data-action="assistant">${icon('spark')}<span>记录日程，或向AI提问</span></button><button class="mic" data-action="voice" aria-label="语音输入">${icon('mic')}</button></div>`;$('#nav').innerHTML=[['today','今日','home'],['schedule','日程','calendar'],['plans','计划','plan'],['semester','学期','book']].map(([v,n,i])=>`<button data-action="${v}" class="${state.view===v?'selected':''}" aria-current="${state.view===v?'page':'false'}">${icon(i)}${n}</button>`).join('');document.querySelectorAll('.review-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.action===state.view));const desc={today:['今日安排','课程在首屏展示，个人计划和统计通过卡片进入。',['点日期查看当天','查看日程详情','直接语音输入']],analytics:['统计分析','时间范围、主分类和标签共同筛选，下方列表显示统计来源。',['点击分类或标签','切换已安排／实际记录','点日期查看日程']],schedule:['日程衔接视图','用于查看确认后的课程、活动和个人计划。完整设计在第二批。',['按日期查看','检查新组会','进入统计分析']],plans:['计划衔接视图','用于确认调整结果与撤销。完整设计在第二批。',['查看报告安排','撤销调整','保留已添加组会']],semester:['学期衔接视图','统计页从这里进入。完整的学期浏览设计在第二批。',['打开统计分析','查看近期事项']]}[state.view];$('#review-title').textContent=desc[0];$('#review-description').textContent=desc[1];$('#review-features').innerHTML=desc[2].map(t=>`<div class="feature">${t}</div>`).join('');animateTotal(previousMinutes);if(!reduced()){document.querySelectorAll('.category-bar').forEach(el=>{const fill=el.querySelector('.bar-fill');const next=fill.offsetWidth;fill.style.animation='none';fill.animate([{width:(previousWidths.get(el.dataset.category)||0)+'px'},{width:next+'px'}],{duration:360,easing:'cubic-bezier(.2,.7,.25,1)'});});}}
function navigate(view){if(state.modal)closeSheet();scrollByView[state.view]=$('#main').scrollTop;state.view=view;render({keepScroll:false});$('#main').scrollTop=scrollByView[view]||0;}
function animateTotal(previous=0){cancelAnimationFrame(numberFrame);const el=$('#animated-total');if(!el||reduced()||(state.metric==='actual'&&Number(el.dataset.known)===0))return;const total=Number(el.dataset.minutes);const start=performance.now();const frame=now=>{const p=Math.min(1,(now-start)/360);el.textContent=hourLabel(previous+(total-previous)*(1-(1-p)**3));if(p<1)numberFrame=requestAnimationFrame(frame);};numberFrame=requestAnimationFrame(frame);}
function openSheet(type,stage){returnFocus=document.activeElement;state.modal=type;if(stage)state.stage=stage;drawSheet();}
function closeSheet(){clearTimeout(processTimer);state.modal=null;$('#overlay').hidden=true;$('#overlay').innerHTML='';['#header','#main','#dock','#nav'].forEach(id=>$(id).inert=false);if(returnFocus?.isConnected)returnFocus.focus();else $('#dock .ask').focus();}
function sheet(title,body){$('#overlay').hidden=false;$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-heading"><div class="handle"></div><div class="sheet-title"><h2 id="sheet-heading">${state.modal==='assistant'?icon('spark'):''}${title}</h2><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="sheet-scroll">${body}</div></section>`;['#header','#main','#dock','#nav'].forEach(id=>$(id).inert=true);$('.close').focus();}
function sourceBubble(){return `<div class="source-bubble"><small>示例通知</small>${esc(state.text||FIXTURE)}</div>`;}
function assistantBody(){switch(state.stage){case 'input':return `<p class="assistant-caption">可以粘贴通知，也可以直接提问。</p><div class="composer"><textarea id="prompt" aria-label="输入内容" placeholder="例如：周五18点交报告，提前一天提醒我">${esc(state.text)}</textarea><div class="composer-tools"><button data-action="image" aria-label="添加图片">${icon('image')}</button><button data-action="voice" aria-label="使用语音">${icon('mic')}</button><button class="send" data-action="send" aria-label="发送">${icon('send')}</button></div></div><div class="section-title"><h2>示例</h2></div><button class="suggestion" data-action="example">${icon('calendar')}<span>添加组会并调整冲突计划<small>周三17:00—18:00 · 会议室6412</small></span></button><button class="suggestion" data-action="analytics-query">${icon('chart')}分析本周日程</button>${meeting()?'<button class="text-button" data-action="continue-result">继续查看上次结果</button>':''}<p class="assistant-footnote">原型仅支持示例流程，不调用真实AI。</p>`;
case 'processing':return `${sourceBubble()}<div class="process" role="status" aria-live="polite">${['整理示例通知','核对分类与时间','检查与个人计划的重叠'].map((t,i)=>`<div class="process-step ${i<state.step?'done':i===state.step?'active':''}">${i<state.step?icon('check'):i===state.step?'<i class="spinner"></i>':'<span style="width:14px">·</span>'}${t}</div>`).join('')}</div><button class="secondary" data-action="stop-processing">返回编辑</button>`;
case 'candidate':return `${sourceBubble()}<div class="result-card"><div class="result-kicker">新增日程</div><h3>课题组组会</h3><div class="result-line">${icon('calendar')}<span>9月23日 周三<br><small>17:00—18:00</small></span></div><div class="result-line">${icon('pin')}<span>会议室6412</span></div><div class="result-line">${icon('bell')}<span>提前${state.reminder===60?'1小时':state.reminder+'分钟'}提醒</span><button class="text-button" data-action="reminder" style="min-height:22px;padding:0">修改</button></div><div class="tag-editor"><span class="tag" style="background:${CATEGORY[state.eventCategory].pale};color:${CATEGORY[state.eventCategory].color}">${CATEGORY[state.eventCategory].name}</span>${state.eventTags.map(t=>`<span class="tag label">${TAG_NAMES[t]}</span>`).join('')}<button data-action="labels">修改分类</button></div></div><div class="conflict-note">${icon('info')}与Java报告计划重叠1小时，加入后可调整。</div><button class="primary" data-action="save-event">加入日程</button><button class="text-button" data-action="input">返回编辑</button>`;
case 'saved':return `<div class="success-note">${icon('check')}组会已加入日程</div><div class="result-card"><h3>Java报告计划需要调整</h3><p class="plain-copy">原计划和组会都在周三17:00—18:00。</p></div><button class="primary" data-action="proposal">查看调整方案</button><button class="text-button" data-action="show-schedule">先查看日程</button>`;
case 'proposal':return `<div class="success-note">${icon('check')}组会已保存，仅调整个人计划</div><div class="result-card"><div class="result-kicker">调整1段 · 共1小时</div><h3>Java实验报告</h3><div class="diff-time"><span>原时间</span><b>周三 17:00—18:00</b></div><div class="diff-arrow">${icon('down')}</div><div class="diff-time after"><span>新时间</span><b>周四 16:00—17:00</b></div><p class="diff-explain">周四这一时段可学习，且没有其他安排。安排在周五18:00截止前。</p></div><button class="primary" data-action="apply">应用调整</button><div class="button-row"><button class="secondary" data-action="alternative">更换时间</button><button class="secondary" data-action="close">暂不调整</button></div>`;
case 'receipt':return `<div class="receipt-title"><div class="check-circle">${icon('check')}</div><h3>计划已调整</h3><p>Java报告已改至周四，组会时间未变。</p></div><div class="result-card"><div class="result-line">${icon('plan')}<span>Java实验报告<br><small>9月24日 16:00—17:00</small></span></div><div class="result-line">${icon('calendar')}<span>课题组组会<br><small>9月23日 17:00—18:00</small></span></div></div><button class="primary" data-action="show-plans">查看个人计划</button><div class="button-row"><button class="secondary" data-action="analytics">查看统计</button><button class="secondary" data-action="undo">撤销调整</button></div>`;
case 'query':{const s=selectedSummary();const hasRelevantConflict=conflict()&&s.filtered.some(r=>r.id==='java'||r.id==='meeting-new');return `<span class="tag label">${shortDate(s.from)}—${shortDate(s.to)}${state.category?' · '+CATEGORY[state.category].name:''}</span><div class="result-card"><h3>${hasRelevantConflict?'有1处时间冲突':s.filtered.length?'当前筛选下没有新增冲突':'当前范围暂无记录'}</h3><p class="plain-copy">${hasRelevantConflict?'周三17:00的组会与Java报告计划重叠，可以将报告改到周四16:00。':`当前范围包含${s.filtered.length}条记录，所选分类和标签已应用。具体时间见统计明细。`}</p><div class="result-line">${icon('chart')}<span>所选范围${state.metric==='actual'?'实际记录':'已安排'} ${hourLabel(s.total)}小时</span></div></div><button class="primary" data-action="${hasRelevantConflict?'proposal':'analytics'}">${hasRelevantConflict?'查看调整方案':'查看统计明细'}</button><p class="assistant-footnote">此回答根据原型数据生成，不是模型推理结果。</p>`;}
case 'voice':return `<div class="wave" aria-hidden="true">${Array.from({length:17},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><p class="plain-copy">这里展示录音交互。本原型没有调用麦克风。</p><button class="primary" data-action="example">使用示例转写继续</button><button class="text-button" data-action="input">改用文字输入</button>`;
case 'image':return `<div class="empty-state">${icon('image')}<h3>添加通知图片</h3><p>本原型不读取或上传文件。</p></div><button class="primary" style="margin-top:16px" data-action="example">使用示例通知继续</button>`;
case 'alternative':return '<p class="plain-copy">此原型只预置周四16:00—17:00这一方案。正式版本会根据你的补充重新查询可用时间。</p><button class="primary" data-action="proposal">返回原方案</button><button class="text-button" data-action="close">暂不调整</button>';
case 'unsupported':return '<p class="plain-copy">原型未接入真实AI，暂时不能处理这段输入。文字已保留。</p><button class="primary" data-action="input">返回编辑</button><button class="text-button" data-action="example">查看组会示例</button>';
}}
function drawSheet(){if(state.modal==='assistant'){const title={candidate:'确认日程',proposal:'调整计划',receipt:'操作结果',voice:'语音输入',image:'图片录入'}[state.stage]||'AI助手';sheet(title,assistantBody());return;}
if(state.modal==='detail'){const r=rows.find(r=>r.id===state.detail);sheet('日程详情',`<div class="result-card"><div class="result-kicker">${CATEGORY[r.category].name}</div><h3>${r.title}</h3><div class="result-line">${icon('calendar')}<span>${dateLabel(r.date)} 周${weekday(r.date)}<br><small>${r.start?`${r.start}—${r.end}`:r.due+'截止'}</small></span></div>${r.place?`<div class="result-line">${icon('pin')}<span>${r.place}</span></div>`:''}<div class="tag-editor">${r.tags.map(t=>`<span class="tag label">${TAG_NAMES[t]}</span>`).join('')}</div></div><button class="primary" data-action="assistant">向AI提问</button>`);return;}
if(state.modal==='labels'){sheet('分类与标签',`<p class="plain-copy">选择一个主分类，保留需要的标签。</p><div class="label-options">${Object.entries(CATEGORY).map(([id,c])=>`<button data-action="event-category" data-category="${id}" class="${state.eventCategory===id?'selected':''}">${c.name}</button>`).join('')}</div><div class="label-options">${['meeting','project'].map(t=>`<button data-action="event-tag" data-tag="${t}" class="${state.eventTags.includes(t)?'selected':''}">${TAG_NAMES[t]}</button>`).join('')}</div><button class="primary" data-action="labels-done">确认分类</button>`);return;}
if(state.modal==='reminder'){sheet('提醒时间',`<label class="field">开始前<select id="reminder"><option value="15" ${state.reminder===15?'selected':''}>15分钟</option><option value="30" ${state.reminder===30?'selected':''}>30分钟</option><option value="60" ${state.reminder===60?'selected':''}>1小时</option></select></label><button class="primary" data-action="reminder-done">确认提醒</button>`);return;}
if(state.modal==='stat-info'){sheet('统计说明','<p class="plain-copy">已安排时长：按日程的开始、结束时间计算。重叠安排分别计时，因此不等于日历实际占用的时长。</p><p class="plain-copy">实际记录时长：只统计已填写的实际时长，没有记录不按零计算。课程时段不自动视为实际出席。</p><p class="plain-copy">多标签同时选择时，每条安排只计一次。只有截止时间的事项不计时长。图表中的数值来自本原型的合成日程。</p>');return;}
if(state.modal==='modules'){sheet('快捷模块',`<p class="plain-copy">今日课程和紧急事项始终显示。</p><button class="quiet-link" data-action="toggle-module">统计与个人计划模块<span>${state.moduleVisible?'显示中':'已隐藏'}</span></button><button class="primary" style="margin-top:15px" data-action="close">完成</button>`);return;}
sheet('账户与设置',`<button class="quiet-link" data-action="offline">${state.offline?'恢复在线状态':'体验离线状态'}${icon('right')}</button><button class="quiet-link" data-action="modules">首页模块${icon('right')}</button><button class="quiet-link" data-action="reduce-motion">减少动画${icon('right')}</button><p class="assistant-footnote">设计原型，没有连接真实账号。</p>`);}
function beginExample(){if(state.offline){notify('当前离线，示例文字已保留');state.text=FIXTURE;return;}state.text=FIXTURE;if(meeting()){openSheet('assistant',state.moved?'receipt':'proposal');return;}state.step=0;openSheet('assistant','processing');const next=()=>{if(state.modal!=='assistant'||state.stage!=='processing')return;state.step++;if(state.step===3)state.stage='candidate';drawSheet();if(state.step<3)processTimer=setTimeout(next,reduced()?0:420);};processTimer=setTimeout(next,reduced()?0:350);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
if(['today','analytics','schedule','plans','semester'].includes(a)){navigate(a);return;}
switch(a){case 'back':navigate('today');break;case 'day':state.day=b.dataset.day;render({keepScroll:false});break;case 'close':closeSheet();break;
case 'assistant':openSheet('assistant','input');break;case 'input':case 'stop-processing':clearTimeout(processTimer);openSheet('assistant','input');break;case 'voice':case 'image':state.text=$('#prompt')?.value||state.text;openSheet('assistant',a);break;
case 'example':beginExample();break;case 'send':state.text=$('#prompt').value.trim();if(!state.text){notify('先输入内容');return;}if(state.offline){notify('离线时仅保留草稿');return;}if(state.text===FIXTURE)beginExample();else openSheet('assistant','unsupported');break;
case 'save-event':if(state.offline){notify('当前离线，尚未保存');return;}if(!meeting())rows.push({id:'meeting-new',date:TODAY,title:'课题组组会',start:'17:00',end:'18:00',category:state.eventCategory,tags:[...state.eventTags],kind:'activity',place:'会议室6412',actual:null,reminder:state.reminder});render();openSheet('assistant','saved');break;
case 'proposal':case 'replan':if(state.offline){notify('联网后再调整，现有安排已保留');return;}openSheet('assistant',meeting()?(state.moved?'receipt':'proposal'):'input');break;
case 'apply':if(state.offline){notify('尚未应用，请联网后再试');return;}Object.assign(rows.find(r=>r.id==='java'),{date:'2026-09-24',start:'16:00',end:'17:00'});state.moved=true;state.undoAvailable=true;render();openSheet('assistant','receipt');break;
case 'undo':if(state.offline){notify('联网后才能撤销');return;}if(!state.undoAvailable){notify('当前没有可撤销的调整');return;}Object.assign(rows.find(r=>r.id==='java'),{date:TODAY,start:'17:00',end:'18:00'});state.moved=false;state.undoAvailable=false;closeSheet();render();notify('计划调整已撤销，组会仍保留');break;
case 'alternative':openSheet('assistant','alternative');break;case 'continue-result':openSheet('assistant',state.moved?'receipt':'proposal');break;
case 'show-plans':navigate('plans');break;case 'show-schedule':state.day=TODAY;navigate('schedule');break;
case 'analytics-query':if(state.view!=='analytics'){state.range='week';state.metric='scheduled';state.category=null;state.tags=[];state.filterDay=null;state.empty=false;}if(state.offline){notify('离线时暂不生成新分析');return;}openSheet('assistant','query');break;
case 'range':state.range=b.dataset.range;state.filterDay=null;state.expanded=false;render();break;
case 'category':state.category=state.category===b.dataset.category?null:b.dataset.category;state.tags=[];state.filterDay=null;state.expanded=false;render();break;
case 'tag':state.tags=state.tags.includes(b.dataset.tag)?state.tags.filter(t=>t!==b.dataset.tag):[...state.tags,b.dataset.tag];state.filterDay=null;state.expanded=false;render();break;
case 'clear-filter':state.category=null;state.tags=[];state.filterDay=null;render();break;
case 'chart-day':if(b.dataset.single==='true'){state.filterDay=state.filterDay===b.dataset.day?null:b.dataset.day;render();}else{openSheet('bucket');sheet(`${dateLabel(b.dataset.day)}—${dateLabel(b.dataset.end)}`,`<div class="detail-list">${selectedSummary().filtered.filter(r=>r.date>=b.dataset.day&&r.date<=b.dataset.end).map(detailEntry).join('')||'<p class="plain-copy">这段时间暂无记录。</p>'}</div>`);}break;
case 'clear-day':state.filterDay=null;render();break;case 'expand-list':state.expanded=true;render();break;
case 'detail':state.detail=b.dataset.id;openSheet('detail');break;case 'labels':openSheet('labels');break;case 'event-category':state.eventCategory=b.dataset.category;drawSheet();break;
case 'event-tag':state.eventTags=state.eventTags.includes(b.dataset.tag)?state.eventTags.filter(t=>t!==b.dataset.tag):[...state.eventTags,b.dataset.tag];drawSheet();break;
case 'labels-done':openSheet('assistant','candidate');break;case 'reminder-done':state.reminder=Number($('#reminder').value);openSheet('assistant','candidate');break;
case 'toggle-module':state.moduleVisible=!state.moduleVisible;render();drawSheet();break;
case 'offline':state.offline=!state.offline;document.querySelector('.review-tools [data-action=offline]').setAttribute('aria-pressed',state.offline);render();if(state.modal)drawSheet();break;
case 'reduce-motion':document.body.classList.toggle('reduced');cancelAnimationFrame(numberFrame);document.querySelector('[data-action=reduce-motion]').setAttribute('aria-pressed',document.body.classList.contains('reduced'));if($('#animated-total'))$('#animated-total').textContent=state.metric==='actual'&&Number($('#animated-total').dataset.known)===0?'—':hourLabel(Number($('#animated-total').dataset.minutes));break;
case 'empty-stats':state.empty=!state.empty;navigate('analytics');notify(state.empty?'已切换为空数据示例':'已恢复示例数据');break;
case 'reset':clearTimeout(processTimer);state=initial();rows=seedData();Object.keys(scrollByView).forEach(k=>delete scrollByView[k]);closeSheet();document.body.classList.remove('reduced');document.querySelectorAll('[aria-pressed]').forEach(b=>b.setAttribute('aria-pressed','false'));render({keepScroll:false});notify('示例已重置');break;
default:openSheet(a);
}});
document.addEventListener('change',e=>{if(e.target.id==='metric'){state.metric=e.target.value;state.filterDay=null;render();}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeSheet();});
document.addEventListener('keydown',e=>{if(!state.modal)return;if(e.key==='Escape'){closeSheet();return;}if(e.key==='Tab'){const items=[...$('#overlay').querySelectorAll('button:not(:disabled),input,textarea,select')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
render();
